export type Role =
  | 'Super Admin'
  | 'Owner'
  | 'Branch Manager'
  | 'Receptionist'
  | 'Trainer'
  | 'Dietitian'
  | 'Accountant'
  | 'Employee'
  | 'Member';

// App Login Credentials — auto-generated by admin
export interface AppUser {
  id: string;
  username: string;         // auto-generated e.g. MEM00125
  email?: string;           // email address or internal auth email
  password?: string;        // temporary or hashed password
  role: Role;
  linkedId: string;         // memberId or employeeId
  linkedName: string;
  branchId: BranchId;
  createdAt: string;
  createdByAdminId: string;
  isActive: boolean;
  mustChangePassword?: boolean;
  tempPassword?: string;
  whatsappStatus?: 'NOT_SENT' | 'SENDING' | 'SENT' | 'DELIVERED' | 'FAILED';
  whatsappSentAt?: string;
  lastLoginAt?: string;
  lastPasswordResetAt?: string;
  permissions: {
    canViewDashboard: boolean;
    canEditWorkouts: boolean;
    canEditDiets: boolean;
    canViewMembers: boolean;
    canManageFinance: boolean;
    canAccessAdmin: boolean;
  };
}

export type BranchId = 'branch-1' | 'branch-2' | 'branch-3';

export type GoalType = 'Weight Loss' | 'Muscle Building' | 'Body Recomposition' | 'Endurance & Cardio' | 'Rehab & Mobility';

export interface Branch {
  id: BranchId;
  name: string;
  code: string;
  city: string;
  address: string;
  phone: string;
  activeMembers: number;
  currentCheckIns: number;
  monthlyRevenue: number;
  capacity: number;
  manager: string;
}

