  email: string;
  dob: string;
  gender: 'Male' | 'Female' | 'Other';
  heightCm: number;
  weightKg: number;
  startWeightKg: number;
  bmi: number;
  chestCm: number;
  waistCm: number;
  armsCm: number;
  thighsCm: number;
  bloodGroup: string;
  emergencyContactName: string;
  emergencyMobile: string;
  address: string;
  medicalHistory: string;
  goal: GoalType;
  referralSource: string;
  branchId: BranchId;
  planId: string;
  planName: string;
  startDate: string;
  endDate: string;
  expiryDate?: string;
  status: 'Active' | 'Expiring Soon' | 'Expired' | 'Cancelled' | 'Renewal Due' | 'Suspended' | 'Pending Payment';
  assignedTrainerId?: string;
  assignedDietitianId?: string;
  rewardPoints: number;
